(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;if(root)root.DistrictPreview=api;})(typeof window==='object'?window:null,()=>{
  const ops=['add','sub','mul','div'],paths=[...ops,'mixed'];
  const names={add:'Addition',sub:'Subtraction',mul:'Multiplication',div:'Division',mixed:'Mixed'},symbols={add:'+',sub:'−',mul:'×',div:'÷',mixed:'✦'},totals={add:121,sub:231,mul:91,div:156};
  const clamp=n=>Math.max(0,Math.min(1,n));
  function operationScore(o){return .8*clamp(o.milestones/(o.total*4))+.2*(o.retained?1:Math.min(2,o.passes)/3);}
  function mixedScore(s){return s.mixed.retained?1:Math.min(2,s.mixed.passes)/3;}
  function hasTrophy(s,op){if(op==='mixed')return ops.every(p=>hasTrophy(s,p))&&s.mixed.retained;const p=s.operations[op];return p.confirmed===p.total&&p.retained;}
  function percentage(s,p){return Math.floor(100*(p==='mixed'?mixedScore(s):operationScore(s.operations[p]))+1e-8);}
  function overall(s){return Math.floor(paths.reduce((sum,p)=>sum+percentage(s,p),0)/5);}
  function trophyCount(s){return paths.filter(p=>hasTrophy(s,p)).length;}
  function support(s){if(!s.sessions)return{key:'not-started',label:'Not started',detail:'Help this student complete a first check.',attention:true,priority:0};if(trophyCount(s)===5)return{key:'complete',label:'Five trophies earned',detail:'Keep confirmed facts fresh with maintenance practice.',attention:false,priority:5};if(s.lastPracticeDays>=3)return{key:'practice-gap',label:'Practice gap',detail:'Reconnect with a short session. Last practice '+s.lastPracticeDays+' school days ago.',attention:true,priority:1};if(s.stalled)return{key:'stalled',label:'Checks need a closer look',detail:'Example check scores have stayed flat. Review strategies and response conditions.',attention:true,priority:2};const refreshing=ops.reduce((n,p)=>n+s.operations[p].refresh,0);if(refreshing)return{key:'review',label:'Facts need refreshing',detail:refreshing+' previously confirmed facts need another look.',attention:true,priority:3};return{key:'building',label:'Building steadily',detail:'Keep practicing and return for the next spaced check.',attention:false,priority:4};}
  function nextStep(s){const status=support(s);if(status.attention)return status.detail;if(trophyCount(s)===5)return status.detail;const remaining=ops.filter(p=>!hasTrophy(s,p));if(!remaining.length)return'Finish the remaining balanced mixed checks to earn the fifth trophy.';const weakest=remaining.sort((a,b)=>percentage(s,a)-percentage(s,b))[0],o=s.operations[weakest];return o.confirmed===o.total?'Return for the next '+names[weakest].toLowerCase()+' check on a different day.':'Keep building '+names[weakest].toLowerCase()+': '+(o.total-o.confirmed)+' facts are not yet confirmed.';}
  function createStudents(){const first=['Alex','Jordan','Morgan','Casey','Riley','Taylor','Avery','Cameron','Skyler','Quinn','Jamie','Rowan'],levels=[0,.03,.13,.22,.31,.41,.53,.65,.77,.87,.97,1],students=[];for(let grade=6;grade<=12;grade++)for(let i=0;i<12;i++){const level=levels[i],s={id:'example-g'+grade+'-'+String(i+1).padStart(2,'0'),name:first[(i+grade-6)%first.length]+' Example',grade,school:grade<=8?'middle':'high',className:'Example class '+String.fromCharCode(65+grade%3),sessions:i?Math.max(1,Math.round(level*24)):0,lastPracticeDays:i===1?4:0,stalled:i===2,operations:{},mixed:{passes:0,retained:false},updated:false};for(let j=0;j<4;j++){const op=ops[j],total=totals[op],fraction=i>=10?1:i===0?0:clamp(level+Math.sin((grade+i+j)*1.7)*.14),confirmed=Math.floor(total*Math.pow(fraction,3)),passes=i>=10?3:Math.min(2,Math.floor(fraction*3));s.operations[op]={total,milestones:Math.floor(total*4*fraction),confirmed,passes,retained:i>=10,refresh:i===3&&op==='div'?3:0};}s.mixed={passes:i===11?3:i===10?2:Math.min(2,Math.floor(level*3)),retained:i===11};students.push(s);}return students;}
  function select(students,{grade=6,school='all',search='',filter='all',sort='least'}={}){return students.filter(s=>(grade==='all'||s.grade===Number(grade))&&(school==='all'||s.school===school)&&s.name.toLowerCase().includes(search.trim().toLowerCase())&&(filter==='all'||filter==='attention'&&support(s).attention||filter==='started'&&s.sessions>0||filter==='complete'&&trophyCount(s)===5)).sort((a,b)=>{if(sort==='most')return overall(b)-overall(a)||a.id.localeCompare(b.id);if(sort==='name')return a.name.localeCompare(b.name)||a.grade-b.grade;if(sort==='attention')return support(a).priority-support(b).priority||overall(a)-overall(b)||a.id.localeCompare(b.id);return overall(a)-overall(b)||a.id.localeCompare(b.id);});}
  function summary(students){return{count:students.length,started:students.filter(s=>s.sessions>0).length,average:students.length?Math.round(students.reduce((n,s)=>n+overall(s),0)/students.length):0,attention:students.filter(s=>support(s).attention).length,notStarted:students.filter(s=>!s.sessions).length,complete:students.filter(s=>trophyCount(s)===5).length};}
  function update(s){const op=ops.filter(p=>s.operations[p].milestones<s.operations[p].total*4).sort((a,b)=>percentage(s,a)-percentage(s,b))[0];if(!op)return false;const o=s.operations[op];o.milestones=Math.min(o.total*4,o.milestones+Math.ceil(o.total*4*.25));o.confirmed=Math.max(o.confirmed,o.milestones-o.total*3);s.sessions++;s.lastPracticeDays=0;s.updated=true;return true;}
  return{ops,paths,names,symbols,totals,operationScore,mixedScore,percentage,overall,hasTrophy,trophyCount,support,nextStep,createStudents,select,summary,update};
});
